@Test
public void testColumnErrors() throws Exception {
    SemanticException e;
    e = getSemanticExceptionInRewrite("select msr11 + msr2 from basecube" + " where " + TWO_DAYS_RANGE, conf);
    assertEquals(e.getCanonicalErrorMsg().getErrorCode(), ErrorMsg.EXPRESSION_NOT_IN_ANY_FACT.getErrorCode());
    // no fact has the all the dimensions queried
    e = getSemanticExceptionInRewrite("select dim1, stateid, msr3, msr13 from basecube" + " where " + TWO_DAYS_RANGE, conf);
    assertEquals(e.getCanonicalErrorMsg().getErrorCode(), ErrorMsg.NO_CANDIDATE_FACT_AVAILABLE.getErrorCode());
    PruneCauses.BriefAndDetailedError pruneCauses = extractPruneCause(e);
    String regexp = String.format(CandidateTablePruneCause.CandidateTablePruneCode.COLUMN_NOT_FOUND.errorFormat, "Column Sets: (.*?)", "queriable together");
    Matcher matcher = Pattern.compile(regexp).matcher(pruneCauses.getBrief());
    assertTrue(matcher.matches(), pruneCauses.getBrief());
    assertEquals(matcher.groupCount(), 1);
    String columnSetsStr = matcher.group(1);
    assertNotEquals(columnSetsStr.indexOf("stateid"), -1);
    assertNotEquals(columnSetsStr.indexOf("msr3, msr13"), -1);
    assertEquals(pruneCauses.getDetails().get("testfact3_base,testfact3_raw_base"), Arrays.asList(CandidateTablePruneCause.columnNotFound("stateid")));
    assertEquals(pruneCauses.getDetails().get("testfact_deprecated,testfact2_raw_base,testfact2_base"), Arrays.asList(CandidateTablePruneCause.columnNotFound("msr3", "msr13")));
    assertTrue(pruneCauses.getDetails().containsKey("testfact1_base,testfact1_raw_base") || pruneCauses.getDetails().containsKey("testfact1_raw_base,testfact1_base"));
    String fact1BaseKey = pruneCauses.getDetails().containsKey("testfact1_base,testfact1_raw_base") ? "testfact1_base,testfact1_raw_base" : "testfact1_raw_base,testfact1_base";
    assertEquals(pruneCauses.getDetails().get(fact1BaseKey), Arrays.asList(new CandidateTablePruneCause(CandidateTablePruneCode.ELEMENT_IN_SET_PRUNED)));
}

