@Test
public void testMaxUpdatePeriodInInterval() throws Exception {
    Set<UpdatePeriod> allPeriods = new HashSet<UpdatePeriod>();
    allPeriods.addAll(Arrays.asList(UpdatePeriod.values()));
    int i = 0;
    Assert.assertEquals(UpdatePeriod.WEEKLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Jan-01 to 2013-Jan-31");
    i += 2;
    Assert.assertEquals(UpdatePeriod.QUARTERLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Jan-01 to 2013-May-31");
    i += 2;
    Assert.assertEquals(UpdatePeriod.QUARTERLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Jan-01 to 2013-Dec-31");
    i += 2;
    Assert.assertEquals(UpdatePeriod.MONTHLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Feb-01 to 2013-Apr-25");
    i += 2;
    Assert.assertEquals(UpdatePeriod.QUARTERLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2012-Feb-01 to 2013-Feb-01");
    i += 2;
    Assert.assertEquals(UpdatePeriod.YEARLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2011-Feb-01 to 2013-Feb-01");
    i += 2;
    Assert.assertEquals(UpdatePeriod.WEEKLY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Feb-01 to 2013-Feb-21");
    i += 2;
    Assert.assertEquals(UpdatePeriod.DAILY, CubeFactTable.maxIntervalInRange(pairs[i], pairs[i + 1], allPeriods), "2013-Feb-01 to 2013-Feb-4");
}

