@Test
public void testSerialize() throws Exception {
    props.put("separatorChar", ",");
    props.put("quoteChar", "\"");
    props.put(serdeConstants.LIST_COLUMNS, "a,b,c,d");
    props.put(serdeConstants.LIST_COLUMN_TYPES, "string,varchar(20),int,char(10)");
