/**
 * Test lens server dao.
 *
 * @throws Exception the exception
 */
@Test
public void testLensServerDAO() throws Exception {
    QueryExecutionServiceImpl service = (QueryExecutionServiceImpl) LensServices.get().getService("query");
    // Test insert query
    QueryContext queryContext = service.createContext("SELECT ID FROM testTable", "foo@localhost", new LensConf(), new Configuration());
    long submissionTime = queryContext.getSubmissionTime();
    queryContext.setQueryName("daoTestQuery1");
    FinishedLensQuery finishedLensQuery = new FinishedLensQuery(queryContext);
    finishedLensQuery.setStatus(QueryStatus.Status.SUCCESSFUL.name());
    // Validate JDBC driver RS Meta can be deserialized
    // Create a valid JDBCResultSet
    Connection conn = null;
    Statement stmt = null;
    final ObjectMapper MAPPER = new ObjectMapper();
    try {
        conn = service.lensServerDao.getConnection();
        stmt = conn.createStatement(ResultSet.TYPE_SCROLL_INSENSITIVE, ResultSet.CONCUR_READ_ONLY);
        ResultSet rs = stmt.executeQuery("SELECT handle FROM finished_queries");
        JDBCResultSet jdbcResultSet = new JDBCResultSet(null, rs, false);
        JDBCResultSet.JDBCResultSetMetadata jdbcRsMeta = (JDBCResultSet.JDBCResultSetMetadata) jdbcResultSet.getMetadata();
        String jsonMetadata = MAPPER.writeValueAsString(jdbcRsMeta);
        log.info("@@@JSON {}" + jsonMetadata);
        finishedLensQuery.setMetadata(MAPPER.writeValueAsString(jdbcRsMeta));
        finishedLensQuery.setMetadataClass(JDBCResultSet.JDBCResultSetMetadata.class.getName());
    } catch (SQLException ex) {
        log.error("Error creating result set ", ex);
    } finally {
        if (stmt != null) {
            stmt.close();
        }
        if (conn != null) {
            conn.close();
        }
    }
    String finishedHandle = finishedLensQuery.getHandle();
    service.lensServerDao.insertFinishedQuery(finishedLensQuery);
    // Re-insert should be a no-op on the db.
    service.lensServerDao.insertFinishedQuery(finishedLensQuery);
    FinishedLensQuery actual = service.lensServerDao.getQuery(finishedHandle);
    // Try to read back result set metadata class, should not throw deserialize exception
    JDBCResultSet.JDBCResultSetMetadata actualRsMeta = MAPPER.readValue(actual.getMetadata(), JDBCResultSet.JDBCResultSetMetadata.class);
    // Assert
    Assert.assertNotNull(actualRsMeta, "Should be able to read back metadata for jdbc queries");
    // Validate metadat
    Assert.assertEquals(actualRsMeta.getColumns().size(), 1);
    Assert.assertEquals(actualRsMeta.getColumns().get(0).getName().toLowerCase(), "handle");
    Assert.assertEquals(actual.getHandle(), finishedHandle);
    // Test find finished queries
    LensSessionHandle session = service.openSession("foo@localhost", "bar", new HashMap<String, String>());
    List<QueryHandle> persistedHandles = service.lensServerDao.findFinishedQueries(null, null, null, submissionTime, System.currentTimeMillis());
    if (persistedHandles != null) {
        for (QueryHandle handle : persistedHandles) {
            LensQuery query = service.getQuery(session, handle);
            if (!handle.getHandleId().toString().equals(finishedHandle)) {
                Assert.assertTrue(query.getStatus().finished(), query.getQueryHandle() + " STATUS=" + query.getStatus().getStatus());
            }
        }
    }
    System.out.println("@@ State = " + queryContext.getStatus().getStatus().name());
    List<QueryHandle> daoTestQueryHandles = service.lensServerDao.findFinishedQueries(finishedLensQuery.getStatus(), queryContext.getSubmittedUser(), "daotestquery1", -1L, Long.MAX_VALUE);
    Assert.assertEquals(daoTestQueryHandles.size(), 1);
    Assert.assertEquals(daoTestQueryHandles.get(0).getHandleId().toString(), finishedHandle);
}

/**
 * Test launch fail.
 *
 * @throws InterruptedException the interrupted exception
 */
@Test
public void testEmailNotification() throws InterruptedException {
    wiser.start();
    LensConf conf = new LensConf();
    // launch failure
    QueryHandle handle = launchAndWaitForQuery(conf, "select ID from non_exist_table", QueryStatus.Status.FAILED);
    List<WiserMessage> messages = new ArrayList<WiserMessage>();
    for (int i = 0; i < NUM_ITERS; i++) {
        messages = wiser.getMessages();
        if (messages.size() >= 4) {
            break;
        }
        Thread.sleep(10000);
    }
    Assert.assertEquals(messages.size(), 4);
    Assert.assertTrue(messages.get(0).toString().contains(handle.toString()));
    Assert.assertTrue(messages.get(0).toString().contains("Launching query failed"));
    Assert.assertTrue(messages.get(0).toString().contains("Reason"));
    // rewriter failure
    handle = launchAndWaitForQuery(conf, "cube select ID from nonexist", QueryStatus.Status.FAILED);
    messages = new ArrayList<WiserMessage>();
    for (int i = 0; i < NUM_ITERS; i++) {
        messages = wiser.getMessages();
        if (messages.size() >= 8) {
            break;
        }
        Thread.sleep(10000);
    }
    Assert.assertEquals(messages.size(), 8);
    Assert.assertTrue(messages.get(4).toString().contains(handle.toString()));
    Assert.assertTrue(messages.get(4).toString().contains("Launching query failed"));
    Assert.assertTrue(messages.get(4).toString().contains("Reason"));
    // formatting failure
    conf = new LensConf();
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_SET, "true");
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, "false");
    conf.addProperty(LensConfConstants.QUERY_OUTPUT_SERDE, "NonexistentSerde.class");
    handle = launchAndWaitForQuery(conf, "select ID, IDSTR from " + TEST_TABLE, QueryStatus.Status.FAILED);
    messages = new ArrayList<WiserMessage>();
    for (int i = 0; i < NUM_ITERS; i++) {
        messages = wiser.getMessages();
        if (messages.size() >= 12) {
            break;
        }
        Thread.sleep(10000);
    }
    Assert.assertEquals(messages.size(), 12);
    Assert.assertTrue(messages.get(8).toString().contains(handle.toString()));
    Assert.assertTrue(messages.get(8).toString().contains("Result formatting failed!"));
    Assert.assertTrue(messages.get(8).toString().contains("Reason"));
    // execution failure
    conf = new LensConf();
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, "true");
    conf.addProperty(HiveConf.ConfVars.COMPRESSRESULT.name(), "true");
    conf.addProperty("mapred.compress.map.output", "true");
    conf.addProperty("mapred.map.output.compression.codec", "nonexisting");
    handle = launchAndWaitForQuery(conf, "select count(ID) from " + TEST_TABLE, QueryStatus.Status.FAILED);
    messages = new ArrayList<WiserMessage>();
    for (int i = 0; i < NUM_ITERS; i++) {
        messages = wiser.getMessages();
        if (messages.size() >= 16) {
            break;
        }
        Thread.sleep(10000);
    }
    Assert.assertEquals(messages.size(), 16);
    Assert.assertTrue(messages.get(12).toString().contains(handle.toString()));
    Assert.assertTrue(messages.get(12).toString().contains("Query execution failed!"));
    Assert.assertTrue(messages.get(12).toString().contains("Reason"));
    // successful query
    conf = new LensConf();
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_SET, "true");
    conf.addProperty(LensConfConstants.QUERY_PERSISTENT_RESULT_INDRIVER, "true");
    handle = launchAndWaitForQuery(conf, "select ID, IDSTR from " + TEST_TABLE, QueryStatus.Status.SUCCESSFUL);
    messages = new ArrayList<WiserMessage>();
    for (int i = 0; i < NUM_ITERS; i++) {
        messages = wiser.getMessages();
        if (messages.size() >= 20) {
            break;
        }
        Thread.sleep(10000);
    }
    Assert.assertEquals(messages.size(), 20);
    Assert.assertTrue(messages.get(16).toString().contains(handle.toString()));
    Assert.assertTrue(messages.get(16).toString().contains("Query  SUCCESSFUL"));
    Assert.assertTrue(messages.get(16).toString().contains("Result available at"));
    wiser.stop();
}

