        stat = ctx2.getStatus();
        Thread.sleep(1000);
    }
    assertEquals(ctx1.getStatus().getStatus(), QueryStatus.Status.SUCCESSFUL);
    // destroy prepared
    APIResult result = target.path(pHandle.toString()).queryParam("sessionid", lensSessionId).request().delete(APIResult.class);
    assertEquals(result.getStatus(), APIResult.Status.SUCCEEDED);
    // Post on destroyed query
    Response response = target.path(pHandle.toString()).request().post(Entity.entity(confpart, MediaType.MULTIPART_FORM_DATA_TYPE), Response.class);
    assertEquals(response.getStatus(), 404);
}

